import json
import re as _re

try:
    _bind = json.loads(bytes.fromhex('5b5b5b2264617461222c2022637573746f6d65724e6f225d2c20227661726961626c65222c2022637573746f6d65724e756d626572225d5d').decode('utf-8'))
    _b = config.get('body')
    if not isinstance(_b, dict):
        _b = dict()
    for _path, _kind, _val in _bind:
        _v = vars.get(_val) if _kind == 'variable' else _val
        if _v is None or _v == '':
            continue
        _o = _b
        for _key in _path[:-1]:
            if not isinstance(_o.get(_key), dict):
                _o[_key] = dict()
            _o = _o[_key]
        _o[_path[-1]] = _v
    config['body'] = _b
except Exception:
    pass

try:
    import urllib.parse as _up
    b = config.get('body')
    if not isinstance(b, dict):
        b = dict()
    url = str(config.get('url') or '')
    for name in _re.findall(r'[{]([A-Za-z_][A-Za-z0-9_]*)[}]', url):
        if b.get(name) is not None:
            url = url.replace(chr(123) + name + chr(125), _up.quote(str(b.pop(name)), safe=''))
    if str(config.get('method') or '').upper() in ('GET', 'DELETE'):
        q = dict((k, v) for k, v in b.items() if v is not None and v != '')
        if q:
            url = url + ('&' if '?' in url else '?') + _up.urlencode(q)
        b = dict()
    config['url'] = url
    config['body'] = b
except Exception:
    pass

